// The class talents ("inherence"): three trees per class, every node one
// learnable talent.  Generated by scripts/gen_talents.py from TALENTS.ZU1
// (the record layout is documented in zu-re/docs/talents.md).
export type TalentNode = {
  id: number;
  name: string;
  // the tooltip text of each rank, rank 1 first - the game writes a fresh
  // szIntro per rank record, so the numbers grow with the rank
  intros: string[];
  // the icon file name, e.g. "ICON_JX_STATIC005" - it is in the class sheet
  icon: string;
  // the node index inside its tree
  node: number;
  // tree points needed to open the node (0, 10, ... 70)
  pointNeed: number;
  // the prerequisite talent's id (0 = none)
  need: number;
  // the prerequisite's node and the rank of it that has to be learned
  needNode: number;
  needRank: number;
  // how many ranks the node has
  ranks: number;
  // the top rank of the ladder
  maxRank: number;
  // the id of every rank, rank 1 first
  rankIds: number[];
  // the top rank's effect list: [type, value] pairs
  effects: [number, number][];
};

export type TalentTree = {
  tree: number;
  nodes: TalentNode[];
};

export type ClassTalents = TalentTree[];

// The tree names per class - the game's own help (HELPMANAGED.ini, "Spending
// talent points"): "Sun Warrior: Fury / Agility / Defense", "Swordsman:
// Gather / Cohesion / Vanish", ...
export const TREE_NAMES: Record<string, [string, string, string]> = {
  sunwarrior: ["Fury", "Agility", "Defense"],
  swordsman: ["Gather", "Cohesion", "Vanish"],
  moonmaiden: ["Hoop", "Nirvana", "Health"],
  beadfairy: ["Wisdom", "Sanctity", "Shield"],
  summoner: ["Anger", "Elffire", "Torment"],
};

// The talent points a character has earned.  The game states that the first
// point comes at level 30 (FLYSWORDBOOK.ini, "Talents Distribution"); the
// cadence itself is a server side rule (see zu-re/docs/talents.md) and is
// not in the shipped data - the app uses one point per 3 levels.
export const FIRST_TALENT_POINT_LEVEL = 30;
export const TALENT_POINTS_PER_LEVEL = 3;
// char_talent_point is a byte in the client, so 255 is the hard maximum
export const MAX_TALENT_POINTS = 255;

export function talentPoints(level: number): number {
  if (level < FIRST_TALENT_POINT_LEVEL) return 0;
  const n = Math.floor((level - FIRST_TALENT_POINT_LEVEL) / TALENT_POINTS_PER_LEVEL) + 1;
  return Math.min(MAX_TALENT_POINTS, n);
}

let cache: Promise<Record<string, ClassTalents>> | null = null;

// the talent node that grants a spell: the node carries the spell's own name
// ("Expose Weakness"), or its rank-1 intro opens with "Teaches you <spell>".
// Every shipped tree spell resolves to exactly one node this way; the base
// "Shapeshift" is the one spell with no node (no point teaches it).
export function taughtBy(trees: ClassTalents | undefined): Map<string, number> {
  const map = new Map<string, number>();
  for (const tree of trees ?? []) {
    for (const node of tree.nodes) {
      map.set(node.name, node.id);
      const m = /^Teaches you (?:the )?(.+?) \(/.exec(node.intros[0] ?? "");
      if (m) map.set(m[1].trim(), node.id);
    }
  }
  return map;
}

// A talent node that changes a spell: its own text talks about the spell by
// name ("Increases damage of Dragon Strike, Double Dragon Strike and Dragon
// Slay spells by 10%").  The node that only TEACHES a spell ("Teaches you
// Expose Weakness") counts too - that is where the spell comes from.
export type SpellAffect = {
  node: TalentNode;
  // the text of the learned rank (the node's own description)
  text: string;
  // the damage bonus the node gives the spell in % (0 when it is not a damage
  // talent): these scale the spell's damage
  dmg: number;
};

// "Increases damage of ... by 10%" / "Increases the damage of ... by 3.8%" /
// "Increases the damage dealt by your ... spell by 22%" - the only talent
// texts that scale the spell's own damage number
const DMG_RE = /Increases (?:the )?damage(?: dealt)? (?:of|by) .*? by (\d+(?:\.\d+)?)%/i;

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// the spells a talent text talks about: the names as whole words, never the
// "SS." copy of another skill ("Learn skills: SS.Thunder Shot"), and never a
// name that only shows up inside a longer one ("Dragon Strike" inside "Double
// Dragon Strike" - but on its own it does count)
function mentioned(text: string, names: { name: string; re: RegExp }[]): string[] {
  const claimed: [number, number][] = [];
  const hits: string[] = [];
  // the longest name first, so its span is claimed before the shorter ones
  for (const n of [...names].sort((a, b) => b.name.length - a.name.length)) {
    let found = false;
    for (const m of text.matchAll(n.re)) {
      const from = m.index!;
      const to = from + m[0].length;
      if (claimed.some(([c, d]) => from < d && to > c)) continue; // inside a longer name
      claimed.push([from, to]);
      found = true;
    }
    if (found) hits.push(n.name);
  }
  return hits;
}

// the learned talent nodes that change each spell
export function spellAffects(
  trees: ClassTalents | undefined,
  names: string[],
  ranks: Record<number, number>,
): Map<string, SpellAffect[]> {
  const res = names.map((name) => ({
    name,
    // the lookbehind keeps the "SS." copies out (they are other spells)
    re: new RegExp(`(?<!SS\\.)\\b${escapeRe(name)}\\b`, "g"),
  }));
  const out = new Map<string, SpellAffect[]>();
  for (const tree of trees ?? []) {
    for (const node of tree.nodes) {
      const rank = ranks[node.id] ?? 0;
      if (rank <= 0) continue; // only a learned node changes anything
      const text = (node.intros[Math.min(rank, node.intros.length) - 1] ?? "").trim();
      const m = DMG_RE.exec(text);
      const dmg = m ? Number(m[1]) : 0;
      for (const nm of mentioned(text, res)) {
        const list = out.get(nm) ?? [];
        list.push({ node, text, dmg });
        out.set(nm, list);
      }
    }
  }
  return out;
}

export function loadTalents(): Promise<Record<string, ClassTalents>> {
  if (!cache) {
    cache = fetch("/data/talents.json").then(
      (r) => r.json() as Promise<Record<string, ClassTalents>>,
    );
  }
  return cache;
}

// The character-wide passive stat lines of the learned talents.  Every one
// carries the "Passive:" marker ("Passive: Increases your defense by 1%")
// while the texts that change single spells name spells and never do — so
// the marker is the exact discriminator between "moves a stat row" and
// "belongs to the Skills tab" (spellAffects).  Each learned rank's own text
// (the same intro the tooltip shows).  The Critical/Garrote DAMAGE-bonus
// passives ("Lethality", "Disabling Hit") and "block chance" change no
// stat row on the panel, so they are not tracked here.
// Returns the % / point sums of the learned ranks plus the per-talent
// list (PlayerStats shows what each learned talent contributes).  The
// per-rank intros are cumulative: rank N's text holds the full N-rank
// value, so the LEARNED rank's text holds the whole contribution.
export type PassiveStats = {
  hpPct: number;
  atkPct: number;
  defPct: number;
  dodge: number;
  garrote: number;
  crit: number;
  parry: number;
  // no stat row exists for these three — the rows only appear when a
  // talent grants them (usePlayerStats)
  critDmg: number;
  garroteDmg: number;
  block: number;
};

const PASSIVE_RES: [keyof PassiveStats, RegExp][] = [
  ["hpPct", /health by ([\d.]+)%/i],
  ["atkPct", /attack power by ([\d.]+)%/i],
  ["defPct", /defense by ([\d.]+)%/i],
  ["dodge", /dodge (?:chance )?by ([\d.]+)%/i],
  ["garrote", /garrote chance by ([\d.]+)%/i],
  ["crit", /critical(?: strike)? chance by ([\d.]+)%/i],
  ["parry", /parry chance by ([\d.]+)%/i],
  ["critDmg", /critical(?: strike)? damage bonus by ([\d.]+)%/i],
  ["critDmg", /damage dealt by your critical hit by ([\d.]+)%/i],
  ["garroteDmg", /garrote damage bonus by ([\d.]+)%/i],
  ["block", /block chance by ([\d.]+)%/i],
];

export function passiveStats(
  trees: ClassTalents | undefined,
  ranks: Record<number, number>,
): PassiveStats {
  const sums: PassiveStats = {
    hpPct: 0, atkPct: 0, defPct: 0, dodge: 0, garrote: 0, crit: 0, parry: 0,
    critDmg: 0, garroteDmg: 0, block: 0,
  };
  for (const tree of trees ?? []) {
    for (const node of tree.nodes) {
      const rank = ranks[node.id] ?? 0;
      if (rank <= 0) continue;
      const text = (node.intros[Math.min(rank, node.intros.length) - 1] ?? "").trim();
      if (!/^Passive:/i.test(text)) continue;
      for (const [key, re] of PASSIVE_RES) {
        const m = re.exec(text);
        if (m) sums[key] += Number(m[1]);
      }
    }
  }
  return sums;
}
